#!/usr/bin/env node
// Bake the World Bible HTML docs (canonical, human-editable) into a
// generated TS module that the runtime can import. Same HTML→text parse
// the ElevenLabs KB sync uses, so the decoupled-stack NPCs and the
// legacy ConvAI agents read identical world facts.
//
// Inputs:
//   docs/backstory.html            — shared facts (who/where/rules)
//   docs/map-fps-shooter.html      — fps_shooter geometry
//   docs/map-arena.html            — arena geometry
//
// Output:
//   packages/shared/src/world-bible.ts  (DO NOT EDIT — regenerated by this script)
//
// Run after editing any doc:
//   pnpm bake:bible

import { readFile, writeFile } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const OUT = resolve(ROOT, 'packages/shared/src/world-bible.ts');

const INPUTS = [
  { key: 'backstory', path: 'docs/backstory.html' },
  { key: 'fps_shooter', path: 'docs/map-fps-shooter.html' },
  { key: 'arena', path: 'docs/map-arena.html' },
];

// ---------- HTML → text (mirrors scripts/upload-knowledge-base.mjs) ----------

function stripDivs(html, openRe) {
  // Cooperative matching div containers using a simple depth counter so we
  // skip nested <div>s correctly.
  let out = '';
  let i = 0;
  while (i < html.length) {
    const m = openRe.exec(html.slice(i));
    if (!m) {
      out += html.slice(i);
      break;
    }
    out += html.slice(i, i + m.index);
    let depth = 1;
    let j = i + m.index + m[0].length;
    while (j < html.length && depth > 0) {
      const nextOpen = html.indexOf('<div', j);
      const nextClose = html.indexOf('</div>', j);
      if (nextClose === -1) break;
      if (nextOpen !== -1 && nextOpen < nextClose) {
        depth += 1;
        j = nextOpen + 4;
      } else {
        depth -= 1;
        j = nextClose + 6;
      }
    }
    i = j;
  }
  return out;
}

function htmlToText(html) {
  const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
  let text = bodyMatch ? bodyMatch[1] : html;

  text = text.replace(/<script[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[\s\S]*?<\/style>/gi, '');

  text = stripDivs(text, /<div\s+id="toolbar"[^>]*>/i);
  text = stripDivs(text, /<div\s+class="doc-nav"[^>]*>/i);
  text = stripDivs(text, /<div\s+class="callout warn"[^>]*>/i);

  text = text.replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n\n# $1\n\n');
  text = text.replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n\n## $1\n\n');
  text = text.replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n\n### $1\n\n');

  text = text.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '- $1\n');
  text = text.replace(/<\/?(ul|ol)[^>]*>/gi, '\n');

  text = text.replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, '$1\n\n');

  text = text.replace(/<\/?(strong|b|em|i|code|span|div|hr|br|a)[^>]*>/gi, ' ');
  text = text.replace(/<[^>]+>/g, '');

  text = text
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&mdash;/g, '—')
    .replace(/&ndash;/g, '–');

  text = text
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return text;
}

// Some preamble lines in the HTMLs only make sense to the editor, not to
// an NPC ("NPCs only read content that lives in the ElevenLabs knowledge
// base... When you finish editing, hit Save..."). Strip them out so the
// LLM doesn't see operator scaffolding.
function stripEditorPreamble(text) {
  return text
    .split('\n')
    .filter((line) => {
      const lower = line.toLowerCase();
      if (lower.includes('eleven labs knowledge base') && lower.includes('only read')) return false;
      if (lower.includes('hit save') && lower.includes('docs/')) return false;
      if (lower.includes('running on stale lore')) return false;
      if (lower.includes('pnpm sync:kb')) return false;
      if (lower.includes('pnpm bake:bible')) return false;
      if (lower.includes('npc personality lives in your system prompt')) return false;
      return true;
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// ---------- Emit ----------

function tsStringLiteral(str) {
  // Backtick string with backslash-escaped backticks and ${ sequences.
  const escaped = str.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');
  return `\`${escaped}\``;
}

async function main() {
  const parsed = {};
  for (const { key, path } of INPUTS) {
    const raw = await readFile(resolve(ROOT, path), 'utf-8');
    const text = stripEditorPreamble(htmlToText(raw));
    parsed[key] = text;
    console.log(`[bake] ${path} → ${text.length} chars`);
  }

  const header = [
    '// AUTO-GENERATED — DO NOT EDIT. Regenerate with `pnpm bake:bible`.',
    '// Sources: docs/backstory.html, docs/map-fps-shooter.html, docs/map-arena.html.',
    '//',
    '// The decoupled-stack orchestrator injects WORLD_BIBLE_SHARED + the',
    '// MAP_BIBLE entry for the active room into every NPC turn\'s system',
    '// prompt. The ElevenLabs KB uploader (`pnpm sync:kb`) parses the same',
    '// HTMLs with matching logic, so both code paths see identical lore.',
    '',
    "import type { MapId } from './maps.js';",
    '',
  ].join('\n');

  const body = [
    `export const WORLD_BIBLE_SHARED: string = ${tsStringLiteral(parsed.backstory)};`,
    '',
    'export const MAP_BIBLE: Record<MapId, string> = {',
    `  fps_shooter: ${tsStringLiteral(parsed.fps_shooter)},`,
    `  arena: ${tsStringLiteral(parsed.arena)},`,
    '};',
    '',
    'export const knowledgeForMap = (id: MapId): string => MAP_BIBLE[id];',
    'export const worldBibleShared = (): string => WORLD_BIBLE_SHARED;',
    '',
  ].join('\n');

  await writeFile(OUT, header + body, 'utf-8');
  console.log(`[bake] wrote ${OUT}`);
}

main().catch((err) => {
  console.error('[bake] failed:', err);
  process.exit(1);
});
